To evaluate the alignment of the two chunks of text, I will use a simple string similarity metric. In this case, I will use the Levenshtein distance, which measures the minimum number of single-character edits (insertions, deletions or substitutions) required to change one word into the other.

However, since the provided chunks are not single words, I will use a more complex approach. I will use the Longest Common Subsequence (LCS) algorithm to find the longest contiguous substring common to both chunks. The ratio of the length of the LCS to the maximum length of the two chunks will be used as a measure of similarity.

Here is the Python code to calculate the similarity:

```python
def levenshtein_distance(s1, s2):
    if len(s1) > len(s2):
        s1, s2 = s2, s1

    distances = range(len(s1) + 1)
    for i2, c2 in enumerate(s2):
        distances_ = [i2+1]
        for i1, c1 in enumerate(s1):
            if c1 == c2:
                distances_.append(distances[i1])
            else:
                distances_.append(1 + min((distances[i1], distances[i1 + 1], distances_[-1])))
        distances = distances_
    return distances[-1]

def longest_common_subsequence(s1, s2):
    m = len(s1)
    n = len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if s1[i - 1] == s2[j - 1]:
            lcs.append(s1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    return ''.join(reversed(lcs))

def calculate_similarity(chunk1, chunk2):
    lcs = longest_common_subsequence(chunk1, chunk2)
    similarity = len(lcs) / max(len(chunk1), len(chunk2))
    return similarity

def evaluate_alignment(chunk1, chunk2):
    similarity = calculate_similarity(chunk1, chunk2)
    if similarity == 0:
        return 0
    elif similarity < 0.2:
        return 0
    elif similarity < 0.4:
        return 1
    elif similarity < 0.6:
        return 2
    elif similarity < 0.8:
        return 3
    elif similarity < 0.9:
        return 4
    else:
        return 5

chunk1 = "-"
chunk2 = "-not aligned-"
label = evaluate_alignment(chunk1, chunk2)
print(label)
